seasons.code:
const HUM = "Hold X near a cold lamp to hum it warm";
Siwi.topdown({
  title: "Hushlight Keeper",
  assets: window.SIWI_ASSETS || {},
  palette: { floor: "#2B3350", floorAlt: "#1E2A4A", wall: "#53648C", wallTop: "#8EA0C8", accent: "#FFC86B", collectible: "#FFE08A", enemy: "#BFD8FF", hazard: "#FF8A8A", player: "#FFC86B" },
  player: { speed: 210, lives: 3 },
  darkness: 0.88,
  light: 175,
  action: "glow",
  goalNeeds: "keys",
  winText: "The beacon is warm again!",
  loseText: "The fog grows cold... try again",
  legend: {
    "C": { type: "collectible", sprite: "collectible", value: 10 },
    "E": { type: "enemy", sprite: "enemy", speed: 60 },
    "F": { type: "enemy", sprite: "enemy2", speed: 50, chase: true, sight: 220 },
    "K": { type: "key", sprite: "key" },
    "D": { type: "door", sprite: "door" },
    "L": { type: "lamp", sprite: "lamp", light: 160 },
    "U": { type: "powerup", sprite: "powerup", power: "light", label: "warm cocoa" },
    "G": { type: "goal", sprite: "goal" }
  },
  levels: [
    {
      name: "Stairlight Halls",
      rows: [
        "##############################",
        "#P....C....C......C.....C....#",
        "#......C.....E.....C.........#",
        "#..L....C......C......F......#",
        "#.....C.....C......C....C....#",
        "#..C......####.....C....E....#",
        "#...C.....####..C.....C......#",
        "#....E......D......F.........#",
        "#..C....C...##.....U...C.....#",
        "#.....C.....##.....K....C....#",
        "#..C.....E......C.....C......#",
        "#......C......L......C.....G.#",
        "##############################"
      ]
    },
    {
      name: "Tidepool Basement",
      rows: [
        "################################",
        "#P....C......C......C.....C....#",
        "#.....E.....C......C...........#",
        "#..L....C.............F........#",
        "#....C.....C.....C.....C.......#",
        "#......######......C....E......#",
        "#..C...######...C.....C........#",
        "#.....C.....D......F...........#",
        "#..C.....C..###.....C....C.....#",
        "#.....U.....###....K....C......#",
        "#..C.....E......C......F.......#",
        "#....C......C......C......C....#",
        "#......C......L.......C.....G..#",
        "################################"
      ]
    }
  ],
  hooks: {
    onLevelStart(api) {
      if (api && api.hint) api.hint("Hum with X, light lamps, find the tide key!");
    },
    onAction(api) {
      if (!api || !api.player) return;
      var p = api.player;
      if (api.burst) api.burst(p.x, p.y - 20, "#FFC86B", 10, 90);
      if (api.floatText) api.floatText("hummm...", p.x, p.y - 34, "#FFE08A");
      if (api.hint) api.hint("Warm humming shooes chilly ghosts!");
    },
    onCollect(item, api) {
      if (api && api.sfx && api.sfx.coin) try { api.sfx.coin(); } catch (e) {}
    },
    onDraw(ctx, api) {
      if (!api || !api.state) return;
      if (api.state.time < 5) {
        var msg = api.state.level === 0 ? "Find key, open beacon door. X = hum glow" : HUM + " + Miff the moth follows you";
        Siwi.text(ctx, msg, api.W / 2, api.H - 66, 18, "#FFE08A", "center");
      }
    }
  }
});
